import{_ as e,o as t,c as s,a5 as p}from"./chunks/framework.DJo0M80U.js";const l=JSON.parse('{"title":"框架概述","description":"","frontmatter":{"title":"框架概述","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","数据库","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第五部分：数据库/02-MyBatis/框架概述.md","filePath":"posts/java快速入门/第五部分：数据库/02-MyBatis/框架概述.md"}'),d={name:"posts/java快速入门/第五部分：数据库/02-MyBatis/框架概述.md"};function a(c,o,r,n,g,_){return t(),s("div",null,[...o[0]||(o[0]=[p("<div><p><strong>什么是框架</strong> 框架（<code>Framework</code>）是整个或部分系统的可重用设计，表现为一组抽象构件及构件实例间交互的方法<code>;</code> 另一种定义认为，框架是可被应用开发者定制的应用骨架。</p><p>前者是从应用方面而后者是从目的方面给出的定义。 简而言之，框架其实就是某种应用的半成品，就是一组组件，供你选用完成你自己的系统。简单说就是使用别人搭好的舞台，你来做表演。而且，框架一般是成熟的，不断升级的软件。 <strong>框架要解决的问题</strong> 框架要解决的最重要的一个问题是技术整合的问题，在 <code>J2EE</code> 的 框架中，有着各种各样的技术，不同的软件企业需要从 <code>J2EE</code> 中选择不同的技术，这就使得软件企业最终的应用依赖于这些技术，技术自身的复杂性和技术的风险性将会直接对应用造成冲击。而应用是软件企业的核心，是竞争力的关键所在，因此应该将应用自身的设计和具体的实现技术解耦。这样，软件企业的研发将集中在应用的设计上，而不是具体的技术实现，技术实现是应用的底层支撑，它不应该直接对应用产生影响。 <strong>框架一般处在低层应用平台（如</strong></p><p><code>J2EE</code></p><p><strong>）和高层业务逻辑之间的中间层。</strong></p><p><strong>软件开发的分层重要性</strong> 框架的重要性在于它实现了部分功能，并且能够很好的将低层应用平台和高层业务逻辑进行了缓和。为了实现软件工程中的“高内聚、低耦合”。把问题划分开来各个解决，易于控制，易于延展，易于分配资源。我们常见的<code>MVC</code> 软件设计思想就是很好的分层思想。</p><p>通过分层更好的实现了各个部分的职责，在每一层将再细化出不同的框架，分别解决各层关注的问题。</p><p><strong>分层开发下的常见框架</strong> 常见的</p><p><code>JavaEE</code></p><p>开发框架：</p><p><code>1</code></p><p><strong>、解决数据的持久化问题的框架</strong><code>MyBatis</code>。作为持久层的框架，还有一个封装程度更高的框架就是<code>Hibernate</code>，但这个框架因为各种原因目前在国内的流行程度下降太多，现在公司开发也越来越少使用。目前使用</p><p><code>Spring Data</code></p><p>来实现数据持久化也是一种趋势。</p><p><code>2</code><strong>、解决</strong> <code>WEB</code> <strong>层问题的</strong> <code>MVC</code> <strong>框架</strong><code>spring MVC</code></p><p><code>3</code>、解决技术整合问题的框架</p><p><code>spring</code></p><p>框架</p></div>",1)])])}const E=e(d,[["render",a]]);export{l as __pageData,E as default};
